1	package dsl
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7	
8		"github.com/alecthomas/participle/v2"
9		"github.com/alecthomas/participle/v2/lexer"
10	)
11	
12	// dslLexer defines the lexical rules for the DSL.
13	var dslLexer = lexer.MustSimple([]lexer.SimpleRule{
14		{Name: "Comment", Pattern: `#[^\n]*`},
15		{Name: "Whitespace", Pattern: `[\s]+`},
16		{Name: "Float", Pattern: `[+-]?[0-9]+\.[0-9]+`},
17		{Name: "Int", Pattern: `[+-]?[0-9]+`},
18		{Name: "String", Pattern: `"(?:[^"\\]|\\.)*"`},
19		{Name: "Arrow", Pattern: `->|→`},
20		{Name: "Ident", Pattern: `[a-zA-Z_][a-zA-Z0-9_\-\.\/]*`},
21		{Name: "LBrace", Pattern: `\{`},
22		{Name: "RBrace", Pattern: `\}`},
23		{Name: "LParen", Pattern: `\(`},
24		{Name: "RParen", Pattern: `\)`},
25		{Name: "LBracket", Pattern: `\[`},
26		{Name: "RBracket", Pattern: `\]`},
27		{Name: "Colon", Pattern: `:`},
28		{Name: "Comma", Pattern: `,`},
29		{Name: "GreaterThan", Pattern: `>`},
30		{Name: "Equals", Pattern: `=`},
31	})
32	
33	// rawParser is the participle parser for the DSL.
34	var rawParser = participle.MustBuild[rawProgram](
35		participle.Lexer(dslLexer),
36		participle.Elide("Comment", "Whitespace"),
37		participle.UseLookahead(3),
38	)
39	
40	// Parse tokenizes and parses a DSL source string into a Program AST.
41	// If the input has syntax errors, Parse attempts error recovery by
42	// splitting the input into top-level blocks and parsing each independently.
43	func Parse(input string) (*Program, []error) {
44		raw, err := rawParser.ParseString("", input)
45		if err == nil {
46			return rawToProgram(raw)
47		}
48	
49		// Error recovery: split input into top-level blocks and parse each
50		blocks := splitTopLevelBlocks(input)
51		if len(blocks) <= 1 {
52			return nil, []error{err}
53		}
54	
55		prog := &Program{}
56		var allErrors []error
57		parsedAny := false
58		for _, block := range blocks {
59			block = strings.TrimSpace(block)
60			if block == "" {
61				continue
62			}
63			r, e := rawParser.ParseString("", block)
64			if e != nil {
65				allErrors = append(allErrors, e)
66				continue
67			}
68			parsedAny = true
69			resolved, lowerErrs := rawToProgram(r)
70			mergeProgram(prog, resolved)
71			allErrors = append(allErrors, lowerErrs...)
72		}
73	
74		if !parsedAny {
75			return nil, []error{err}
76		}
77		return prog, allErrors
78	}
79	
80	// splitTopLevelBlocks splits DSL source into top-level blocks by finding
81	// top-level keywords (SIGNAL, ROUTE, MODEL, PLUGIN) that appear outside of
82	// braces.
83	func splitTopLevelBlocks(input string) []string {
84		var blocks []string
85		depth := 0
86		start := 0
87		keywords := []string{
88			"DECISION_TREE", "ENTRYPOINT", "PROJECTION", "ROUTING", "RECIPE",
89			"SIGNAL", "ROUTE", "MODEL", "PLUGIN", "TEST",
90		}
91	
92		for i := 0; i < len(input); i++ {
93			ch := input[i]
94			if ch == '"' {
95				// skip string literals
96				i++
97				for i < len(input) && input[i] != '"' {
98					if input[i] == '\\' {
99						i++
100					}
101					i++
102				}
103				continue
104			}
105			if ch == '#' {
106				// skip comments
107				for i < len(input) && input[i] != '\n' {
108					i++
109				}
110				continue
111			}
112			if ch == '{' {
113				depth++
114				continue
115			}
116			if ch == '}' {
117				depth--
118				continue
119			}
120			if depth == 0 {
121				for _, kw := range keywords {
122					if i+len(kw) <= len(input) && input[i:i+len(kw)] == kw {
123						// Check that it's at a word boundary
124						if i > 0 && isIdentPart(rune(input[i-1])) {
125							continue
126						}
127						if i+len(kw) < len(input) && isIdentPart(rune(input[i+len(kw)])) {
128							continue
129						}
130						// Found a top-level keyword — split here
131						if i > start {
132							blocks = append(blocks, input[start:i])
133						}
134						start = i
135						break
136					}
137				}
138			}
139		}
140		if start < len(input) {
141			blocks = append(blocks, input[start:])
142		}
143		return blocks
144	}
145	
146	// ---------- Raw → Resolved Conversion ----------
147	
148	func rawToProgram(raw *rawProgram) (*Program, []error) {
149		prog := &Program{}
150		var errs []error
151		hasDirectRoutes := false
152		treeCount := 0
153		for _, entry := range raw.Entries {
154			switch {
155			case entry.Routing != nil:
156				errs = append(errs, applyRawRouting(prog, entry.Routing)...)
157			case entry.Entrypoint != nil:
158				decl, entryErrs := rawToEntrypoint(entry.Entrypoint)
159				prog.Entrypoints = append(prog.Entrypoints, decl)
160				errs = append(errs, entryErrs...)
161			case entry.Recipe != nil:
162				decl, recipeErrs := rawToRecipe(entry.Recipe)
163				prog.Recipes = append(prog.Recipes, decl)
164				errs = append(errs, recipeErrs...)
165			case entry.Signal != nil:
166				prog.Signals = append(prog.Signals, rawToSignal(entry.Signal))
167			case entry.Projection != nil:
168				switch entry.Projection.Kind {
169				case "partition":
170					prog.ProjectionPartitions = append(prog.ProjectionPartitions, rawToProjectionPartition(entry.Projection))
171				case "score":
172					prog.ProjectionScores = append(prog.ProjectionScores, rawToProjectionScore(entry.Projection))
173				case "mapping":
174					prog.ProjectionMappings = append(prog.ProjectionMappings, rawToProjectionMapping(entry.Projection))
175				}
176			case entry.Route != nil:
177				hasDirectRoutes = true
178				prog.Routes = append(prog.Routes, rawToRoute(entry.Route))
179			case entry.DecisionTree != nil:
180				treeCount++
181				routes, treeErrs := rawDecisionTreeToRoutes(entry.DecisionTree, treeCount-1)
182				prog.Routes = append(prog.Routes, routes...)
183				errs = append(errs, treeErrs...)
184			case entry.Model != nil:
185				prog.Models = append(prog.Models, rawToModelDecl(entry.Model))
186			case entry.Plugin != nil:
187				prog.Plugins = append(prog.Plugins, rawToPlugin(entry.Plugin))
188			case entry.TestBlock != nil:
189				prog.TestBlocks = append(prog.TestBlocks, rawToTestBlock(entry.TestBlock))
190			}
191		}
192		if hasDirectRoutes && treeCount > 0 {
193			errs = append(errs, fmt.Errorf("DECISION_TREE and ROUTE declarations cannot coexist in the same program. Use only DECISION_TREE (for if/else conditional logic) or only ROUTE (for priority-based routing with WHEN clauses), not both"))
194		}
195		return prog, errs
196	}
197	
198	func mergeProgram(dst, src *Program) {
199		if src.Strategy != "" {
200			dst.Strategy = src.Strategy
201		}
202		dst.Entrypoints = append(dst.Entrypoints, src.Entrypoints...)
203		dst.Recipes = append(dst.Recipes, src.Recipes...)
204		dst.Signals = append(dst.Signals, src.Signals...)
205		dst.ProjectionPartitions = append(dst.ProjectionPartitions, src.ProjectionPartitions...)
206		dst.ProjectionScores = append(dst.ProjectionScores, src.ProjectionScores...)
207		dst.ProjectionMappings = append(dst.ProjectionMappings, src.ProjectionMappings...)
208		dst.Routes = append(dst.Routes, src.Routes...)
209		dst.Models = append(dst.Models, src.Models...)
210		dst.Plugins = append(dst.Plugins, src.Plugins...)
211		dst.TestBlocks = append(dst.TestBlocks, src.TestBlocks...)
212	}
213	
214	func rawToProjectionPartition(r *rawProjectionDecl) *ProjectionPartitionDecl {
215		partition := &ProjectionPartitionDecl{
216			Name: unquoteIdent(r.Name),
217			Pos:  posFromLexer(r.Pos),
218		}
219		fields := entriesToMap(r.Fields)
220		if v, ok := fields["semantics"]; ok {
221			if sv, ok := v.(StringValue); ok {
222				partition.Semantics = sv.V
223			}
224		}
225		if v, ok := fields["temperature"]; ok {
226			switch tv := v.(type) {
227			case FloatValue:
228				partition.Temperature = tv.V
229			case IntValue:
230				partition.Temperature = float64(tv.V)
231			}
232		}
233		if v, ok := fields["members"]; ok {
234			if av, ok := v.(ArrayValue); ok {
235				for _, item := range av.Items {
236					if sv, ok := item.(StringValue); ok {
237						partition.Members = append(partition.Members, sv.V)
238					}
239				}
240			}
241		}
242		if v, ok := fields["default"]; ok {
243			if sv, ok := v.(StringValue); ok {
244				partition.Default = sv.V
245			}
246		}
247		return partition
248	}
249	
250	func rawToProjectionScore(r *rawProjectionDecl) *ProjectionScoreDecl {
251		score := &ProjectionScoreDecl{
252			Name:   unquoteIdent(r.Name),
253			Pos:    posFromLexer(r.Pos),
254			Method: "weighted_sum",
255		}
256		fields := entriesToMap(r.Fields)
257		if method, ok := getStringField(fields, "method"); ok {
258			score.Method = method
259		}
260		if rawInputs, ok := fields["inputs"].(ArrayValue); ok {
261			for _, item := range rawInputs.Items {
262				ov, ok := item.(ObjectValue)
263				if !ok {
264					continue
265				}
266				input := &ProjectionScoreInputDecl{}
267				if signalType, ok := getStringField(ov.Fields, "type"); ok {
268					input.SignalType = signalType
269				}
270				if signalName, ok := getStringField(ov.Fields, "name"); ok {
271					input.SignalName = signalName
272				}
273				if kb, ok := getStringField(ov.Fields, "kb"); ok {
274					input.KB = kb
275				}
276				if metric, ok := getStringField(ov.Fields, "metric"); ok {
277					input.Metric = metric
278				}
279				if weight, ok := getFloat64Field(ov.Fields, "weight"); ok {
280					input.Weight = weight
281				}
282				if valueSource, ok := getStringField(ov.Fields, "value_source"); ok {
283					input.ValueSource = valueSource
284				}
285				if match, ok := getFloat64Field(ov.Fields, "match"); ok {
286					input.Match = match
287				}
288				if miss, ok := getFloat64Field(ov.Fields, "miss"); ok {
289					input.Miss = miss
290				}
291				score.Inputs = append(score.Inputs, input)
292			}
293		}
294		return score
295	}
296	
297	func rawToProjectionMapping(r *rawProjectionDecl) *ProjectionMappingDecl {
298		mapping := &ProjectionMappingDecl{
299			Name:   unquoteIdent(r.Name),
300			Pos:    posFromLexer(r.Pos),
301			Method: "threshold_bands",
302		}
303		fields := entriesToMap(r.Fields)
304		if source, ok := getStringField(fields, "source"); ok {
305			mapping.Source = source
306		}
307		if method, ok := getStringField(fields, "method"); ok {
308			mapping.Method = method
309		}
310		if calibrationObj, ok := fields["calibration"].(ObjectValue); ok {
311			calibration := &ProjectionMappingCalibrationDecl{}
312			if method, ok := getStringField(calibrationObj.Fields, "method"); ok {
313				calibration.Method = method
314			}
315			if slope, ok := getFloat64Field(calibrationObj.Fields, "slope"); ok {
316				calibration.Slope = slope
317			}
318			mapping.Calibration = calibration
319		}
320		if rawOutputs, ok := fields["outputs"].(ArrayValue); ok {
321			for _, item := range rawOutputs.Items {
322				ov, ok := item.(ObjectValue)
323				if !ok {
324					continue
325				}
326				output := &ProjectionMappingOutputDecl{}
327				if name, ok := getStringField(ov.Fields, "name"); ok {
328					output.Name = name
329				}
330				if v, ok := getFloat64Field(ov.Fields, "lt"); ok {
331					output.LT = float64Ptr(v)
332				}
333				if v, ok := getFloat64Field(ov.Fields, "lte"); ok {
334					output.LTE = float64Ptr(v)
335				}
336				if v, ok := getFloat64Field(ov.Fields, "gt"); ok {
337					output.GT = float64Ptr(v)
338				}
339				if v, ok := getFloat64Field(ov.Fields, "gte"); ok {
340					output.GTE = float64Ptr(v)
341				}
342				mapping.Outputs = append(mapping.Outputs, output)
343			}
344		}
345		return mapping
346	}
347	
348	func float64Ptr(v float64) *float64 {
349		return &v
350	}
351	
352	func rawToTestBlock(r *rawTestBlockDecl) *TestBlockDecl {
353		tb := &TestBlockDecl{
354			Name: unquoteIdent(r.Name),
355			Pos:  posFromLexer(r.Pos),
356		}
357		for _, entry := range r.Entries {
358			tb.Entries = append(tb.Entries, &TestEntry{
359				Query:     unquote(entry.Query),
360				RouteName: unquoteIdent(entry.RouteName),
361				Pos:       posFromLexer(entry.Pos),
362			})
363		}
364		return tb
365	}
366	
367	func rawToSignal(r *rawSignalDecl) *SignalDecl {
368		return &SignalDecl{
369			SignalType: r.SignalType,
370			Name:       unquoteIdent(r.Name),
371			Fields:     entriesToMap(r.Fields),
372			Pos:        posFromLexer(r.Pos),
373		}
374	}
375	
376	func rawToRoute(r *rawRouteDecl) *RouteDecl {
377		route := &RouteDecl{
378			Name: unquoteIdent(r.Name),
379			Pos:  posFromLexer(r.Pos),
380		}
381	
382		// Process options
383		for _, opt := range r.Opts {
384			if opt.Key == "description" && opt.Value != nil && opt.Value.Str != nil {
385				route.Description = unquote(*opt.Value.Str)
386			}
387		}
388	
389		// Process body items
390		for _, item := range r.Body {
391			switch {
392			case item.Priority != nil:
393				route.Priority = *item.Priority
394			case item.Tier != nil:
395				route.Tier = *item.Tier
396			case item.When != nil:
397				route.When = toBoolExpr(item.When)
398			case item.Model != nil:
399				for _, m := range item.Model.Models {
400					route.Models = append(route.Models, rawToModelRef(m))
401				}
402			case item.Algorithm != nil:
403				route.Algorithm = rawToAlgo(item.Algorithm)
404			case item.Plugin != nil:
405				route.Plugins = append(route.Plugins, rawToPluginRef(item.Plugin))
406			case item.Description != nil:
407				route.Description = unquote(*item.Description)
408			case item.CandidateFor != nil:
409				route.CandidateIterations = append(route.CandidateIterations, rawToCandidateIteration(item.CandidateFor))
410			case item.Emit != nil:
411				route.Emits = append(route.Emits, rawToEmitDecl(item.Emit))
412			}
413		}
414	
415		return route
416	}
417	
418	func rawToModelDecl(r *rawModelDecl) *ModelDecl {
419		return &ModelDecl{
420			Name:   unquoteIdent(r.Name),
421			Fields: entriesToMap(r.Fields),
422			Pos:    posFromLexer(r.Pos),
423		}
424	}
425	
426	func rawToPlugin(r *rawPluginDecl) *PluginDecl {
427		return &PluginDecl{
428			Name:       unquoteIdent(r.Name),
429			PluginType: normalizePluginName(r.PluginType),
430			Fields:     entriesToMap(r.Fields),
431			Pos:        posFromLexer(r.Pos),
432		}
433	}
434	
435	func rawToPluginRef(r *rawPluginRef) *PluginRef {
436		ref := &PluginRef{
437			Name: normalizePluginName(unquoteIdent(r.Name)),
438			Pos:  posFromLexer(r.Pos),
439		}
440		if len(r.Fields) > 0 {
441			ref.Fields = entriesToMap(r.Fields)
442		}
443		return ref
444	}
445	
446	// knownInlinePluginAliases maps hyphenated plugin type names to their canonical
447	// underscore form. Only known inline types are normalized; template names pass
448	// through unchanged so "PLUGIN my-template system_prompt {}" keeps its name.
449	var knownInlinePluginAliases = map[string]string{
450		"semantic-cache":     "semantic_cache",
451		"system-prompt":      "system_prompt",
452		"header-mutation":    "header_mutation",
453		"router-replay":      "router_replay",
454		"image-gen":          "image_gen",
455		"fast-response":      "fast_response",
456		"request-params":     "request_params",
457		"response-jailbreak": "response_jailbreak",
458	}
459	
460	// normalizePluginName converts known hyphenated plugin type aliases to their
461	// canonical underscore form. Unknown names (e.g. template references) are
462	// returned unchanged.
463	func normalizePluginName(name string) string {
464		if canonical, ok := knownInlinePluginAliases[name]; ok {
465			return canonical
466		}
467		return name
468	}
469	
470	func rawToAlgo(r *rawAlgoSpec) *AlgoSpec {
471		return &AlgoSpec{
472			AlgoType: r.AlgoType,
473			Fields:   entriesToMap(r.Fields),
474			Pos:      posFromLexer(r.Pos),
475		}
476	}
477	
478	func rawToModelRef(r *rawModelRef) *ModelRef {
479		m := &ModelRef{
480			Model: unquote(r.Model),
481			Pos:   posFromLexer(r.Pos),
482		}
483		for _, opt := range r.Options {
484			if opt.Value == nil {
485				continue
486			}
487			v := opt.Value
488			switch opt.Key {
489			case "reasoning":
490				if v.Bool != nil {
491					b := *v.Bool == "true"
492					m.Reasoning = &b
493				}
494			case "effort":
495				if v.Str != nil {
496					m.Effort = unquote(*v.Str)
497				}
498			case "lora":
499				if v.Str != nil {
500					m.LoRA = unquote(*v.Str)
501				}
502			case "param_size":
503				if v.Str != nil {
504					m.ParamSize = unquote(*v.Str)
505				}
506			case "weight":
507				if v.Int != nil {
508					m.Weight = float64(*v.Int)
509				} else if v.Float != nil {
510					m.Weight = *v.Float
511				}
512			}
513		}
514		return m
515	}
516	
517	// ---------- Boolean Expression Conversion ----------
518	
519	func toBoolExpr(top *BoolExprTop) BoolExpr {
520		if top == nil || len(top.Terms) == 0 {
521			return nil
522		}
523		result := toAndExpr(top.Terms[0])
524		for i := 1; i < len(top.Terms); i++ {
525			right := toAndExpr(top.Terms[i])
526			result = &BoolOr{Left: result, Right: right, Pos: posFromLexer(top.Pos)}
527		}
528		return result
529	}
530	
531	func toAndExpr(term *BoolAndTerm) BoolExpr {
532		if term == nil || len(term.Factors) == 0 {
533			return nil
534		}
535		result := toFactorExpr(term.Factors[0])
536		for i := 1; i < len(term.Factors); i++ {
537			right := toFactorExpr(term.Factors[i])
538			result = &BoolAnd{Left: result, Right: right, Pos: posFromLexer(term.Pos)}
539		}
540		return result
541	}
542	
543	func toFactorExpr(f *BoolFactor) BoolExpr {
544		if f == nil {
545			return nil
546		}
547		pos := posFromLexer(f.Pos)
548		switch {
549		case f.Not != nil:
550			return &BoolNot{Expr: toFactorExpr(f.Not), Pos: pos}
551		case f.Paren != nil:
552			return toBoolExpr(f.Paren)
553		case f.SignalRef != nil:
554			return &SignalRefExpr{
555				SignalType: f.SignalRef.SignalType,
556				SignalName: unquote(f.SignalRef.SignalName),
557				Fields:     entriesToMap(f.SignalRef.Fields),
558				Pos:        pos,
559			}
560		}
561		return nil
562	}
563	
564	// ---------- Field / Value Conversion ----------
565	
566	func entriesToMap(entries []*FieldEntry) map[string]Value {
567		result := make(map[string]Value, len(entries))
568		for _, e := range entries {
569			if e != nil && e.Value != nil {
570				result[e.Key] = valToValue(e.Value)
571			}
572		}
573		return result
574	}
575	
576	func valToValue(v *Val) Value {
577		if v == nil {
578			return nil
579		}
580		switch {
581		case v.Str != nil:
582			return StringValue{V: unquote(*v.Str)}
583		case v.Float != nil:
584			return FloatValue{V: *v.Float}
585		case v.Int != nil:
586			return IntValue{V: *v.Int}
587		case v.Bool != nil:
588			return BoolValue{V: *v.Bool == "true"}
589		case v.ArrayVal != nil:
590			items := make([]Value, 0, len(v.ArrayVal.Items))
591			for _, item := range v.ArrayVal.Items {
592				items = append(items, valToValue(item))
593			}
594			return ArrayValue{Items: items}
595		case v.Object != nil:
596			return ObjectValue{Fields: entriesToMap(v.Object)}
597		case v.BareStr != nil:
598			return StringValue{V: *v.BareStr}
599		}
600		return nil
601	}
602	
603	// ---------- String Helpers ----------
604	
605	// unquote removes surrounding quotes and handles escapes.
606	func unquote(s string) string {
607		if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
608			if unq, err := strconv.Unquote(s); err == nil {
609				return unq
610			}
611			return s[1 : len(s)-1]
612		}
613		return s
614	}
615	
616	// unquoteIdent unquotes a name that may be either a bare ident or a quoted string.
617	func unquoteIdent(s string) string {
618		return unquote(s)
619	}
620	
621	// ---------- Legacy Token/Lex Compatibility ----------
622	
623	// TokenType represents the type of a lexical token.
624	type TokenType int
625	
626	const (
627		TOKEN_EOF TokenType = iota
628		TOKEN_ILLEGAL
629		TOKEN_IDENT
630		TOKEN_STRING
631		TOKEN_INT
632		TOKEN_FLOAT
633		TOKEN_BOOL
634		TOKEN_COMMENT
635		TOKEN_SIGNAL
636		TOKEN_ROUTE
637		TOKEN_PLUGIN
638		TOKEN_PRIORITY
639		TOKEN_WHEN
640		TOKEN_MODEL
641		TOKEN_ALGORITHM
642		TOKEN_FOR
643		TOKEN_IN
644		TOKEN_AND
645		TOKEN_OR
646		TOKEN_NOT
647		TOKEN_LBRACE
648		TOKEN_RBRACE
649		TOKEN_LPAREN
650		TOKEN_RPAREN
651		TOKEN_LBRACKET
652		TOKEN_RBRACKET
653		TOKEN_COLON
654		TOKEN_COMMA
655		TOKEN_EQUALS
656	)
657	
658	func (t TokenType) String() string {
659		names := map[TokenType]string{
660			TOKEN_EOF: "EOF", TOKEN_ILLEGAL: "ILLEGAL", TOKEN_IDENT: "IDENT",
661			TOKEN_STRING: "STRING", TOKEN_INT: "INT", TOKEN_FLOAT: "FLOAT",
662			TOKEN_BOOL: "BOOL", TOKEN_COMMENT: "COMMENT", TOKEN_SIGNAL: "SIGNAL",
663			TOKEN_ROUTE: "ROUTE", TOKEN_PLUGIN: "PLUGIN", TOKEN_PRIORITY: "PRIORITY",
664			TOKEN_WHEN: "WHEN", TOKEN_MODEL: "MODEL", TOKEN_ALGORITHM: "ALGORITHM",
665			TOKEN_FOR: "FOR", TOKEN_IN: "IN", TOKEN_AND: "AND", TOKEN_OR: "OR", TOKEN_NOT: "NOT",
666			TOKEN_LBRACE: "{", TOKEN_RBRACE: "}",
667			TOKEN_LPAREN: "(", TOKEN_RPAREN: ")", TOKEN_LBRACKET: "[",
668			TOKEN_RBRACKET: "]", TOKEN_COLON: ":", TOKEN_COMMA: ",", TOKEN_EQUALS: "=",
669		}
670		if s, ok := names[t]; ok {
671			return s
672		}
673		return fmt.Sprintf("TokenType(%d)", t)
674	}
675	
676	// Token represents a single lexical token.
677	type Token struct {
678		Type    TokenType
679		Literal string
680		Pos     Position
681	}
682	
683	func (t Token) String() string {
684		return fmt.Sprintf("Token(%s, %q, %s)", t.Type, t.Literal, t.Pos)
685	}
686	
687	// Lex tokenizes the DSL source (backward compatibility for validator).
688	func Lex(input string) ([]Token, []error) {
689		lex, err := dslLexer.Lex("", strings.NewReader(input))
690		if err != nil {
691			return nil, []error{err}
692		}
693	
694		keywordMap := map[string]TokenType{
695			"SIGNAL": TOKEN_SIGNAL, "ROUTE": TOKEN_ROUTE,
696			"PLUGIN": TOKEN_PLUGIN, "TEST": TOKEN_IDENT,
697			"PRIORITY": TOKEN_PRIORITY, "TIER": TOKEN_IDENT, "WHEN": TOKEN_WHEN,
698			"MODEL": TOKEN_MODEL, "ALGORITHM": TOKEN_ALGORITHM,
699			"FOR": TOKEN_FOR, "IN": TOKEN_IN,
700			"AND": TOKEN_AND, "OR": TOKEN_OR, "NOT": TOKEN_NOT,
701			"true": TOKEN_BOOL, "false": TOKEN_BOOL,
702		}
703		punctMap := map[lexer.TokenType]TokenType{}
704	
705		symMap := dslLexer.Symbols()
706		identSym := symMap["Ident"]
707		stringSym := symMap["String"]
708		intSym := symMap["Int"]
709		floatSym := symMap["Float"]
710		eofSym := symMap["EOF"]
711		lbraceSym := symMap["LBrace"]
712		rbraceSym := symMap["RBrace"]
713		lparenSym := symMap["LParen"]
714		rparenSym := symMap["RParen"]
715		lbracketSym := symMap["LBracket"]
716		rbracketSym := symMap["RBracket"]
717		colonSym := symMap["Colon"]
718		commaSym := symMap["Comma"]
719		equalsSym := symMap["Equals"]
720		arrowSym := symMap["Arrow"]
721		greaterThanSym := symMap["GreaterThan"]
722		commentSym := symMap["Comment"]
723		wsSym := symMap["Whitespace"]
724	
725		punctMap[lbraceSym] = TOKEN_LBRACE
726		punctMap[rbraceSym] = TOKEN_RBRACE
727		punctMap[lparenSym] = TOKEN_LPAREN
728		punctMap[rparenSym] = TOKEN_RPAREN
729		punctMap[lbracketSym] = TOKEN_LBRACKET
730		punctMap[rbracketSym] = TOKEN_RBRACKET
731		punctMap[colonSym] = TOKEN_COLON
732		punctMap[commaSym] = TOKEN_COMMA
733		punctMap[equalsSym] = TOKEN_EQUALS
734		_ = arrowSym
735		_ = greaterThanSym
736	
737		var tokens []Token
738		for {
739			t, err := lex.Next()
740			if err != nil {
741				return nil, []error{err}
742			}
743	
744			pos := Position{Line: t.Pos.Line, Column: t.Pos.Column}
745	
746			switch t.Type {
747			case eofSym:
748				tokens = append(tokens, Token{Type: TOKEN_EOF, Literal: "", Pos: pos})
749				return tokens, nil
750			case wsSym, commentSym:
751				continue
752			case identSym:
753				if kwType, ok := keywordMap[t.Value]; ok {
754					tokens = append(tokens, Token{Type: kwType, Literal: t.Value, Pos: pos})
755				} else {
756					tokens = append(tokens, Token{Type: TOKEN_IDENT, Literal: t.Value, Pos: pos})
757				}
758			case stringSym:
759				tokens = append(tokens, Token{Type: TOKEN_STRING, Literal: unquote(t.Value), Pos: pos})
760			case intSym:
761				tokens = append(tokens, Token{Type: TOKEN_INT, Literal: t.Value, Pos: pos})
762			case floatSym:
763				tokens = append(tokens, Token{Type: TOKEN_FLOAT, Literal: t.Value, Pos: pos})
764			default:
765				if pType, ok := punctMap[t.Type]; ok {
766					tokens = append(tokens, Token{Type: pType, Literal: t.Value, Pos: pos})
767				}
768			}
769		}
770	}
771	
772	// LookupIdent returns the token type for an identifier string.
773	func LookupIdent(ident string) TokenType {
774		keywords := map[string]TokenType{
775			"SIGNAL": TOKEN_SIGNAL, "ROUTE": TOKEN_ROUTE,
776			"PLUGIN": TOKEN_PLUGIN, "TEST": TOKEN_IDENT,
777			"PRIORITY": TOKEN_PRIORITY, "TIER": TOKEN_IDENT, "WHEN": TOKEN_WHEN,
778			"MODEL": TOKEN_MODEL, "ALGORITHM": TOKEN_ALGORITHM,
779			"FOR": TOKEN_FOR, "IN": TOKEN_IN,
780			"AND": TOKEN_AND, "OR": TOKEN_OR, "NOT": TOKEN_NOT,
781			"true": TOKEN_BOOL, "false": TOKEN_BOOL,
782		}
783		if tok, ok := keywords[ident]; ok {
784			return tok
785		}
786		return TOKEN_IDENT
787	}
788	
789	// isIdentPart returns true if ch is valid in a DSL identifier.
790	func isIdentPart(ch rune) bool {
791		return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
792			(ch >= '0' && ch <= '9') || ch == '_' || ch == '-' || ch == '.' || ch == '/'
793	}
